 const sma20 = lib.sma(closes, 20);

 // momentum signal
 let p_up_close = 0.5;
 if (change < -0.02) p_up_close += 0.15; // mean reversion after drop
 if (change > 0.02) p_up_close -= 0.10; // continuation or fade

 // 1h prediction (mostly flat or slight mean reversion on weekends)
 let p_up_1h = 0.50;
 const h1_change = (h1_closes[h1_closes.length-1] - h1_closes[h1_closes.length-2]) / h1_closes[h1_closes.length-2];
 if (h1_change < -0.01) p_up_1h += 0.10;

 return {
 h1_p: lib.clamp(p_up_1h, 0.3, 0.7),
 close_p: lib.clamp(p_up_close, 0.3, 0.7),
 lastClose,
 h1_last: h1_closes[h1_closes.length-1]
 };
}

const res = {};
['spx', 'ndx', 'tlt', 'boil', 'kospi'].forEach(k => {
 res[k] = analyze(k);
